import csv
from dataclasses import dataclass
from datetime import datetime, timezone
from decimal import Decimal
from pathlib import Path


@dataclass(frozen=True)
class Event:
    category: str
    amount: Decimal
    timestamp: str | None = None


def parse_timestamp(text: str) -> datetime:
    """Parse an ISO timestamp with an explicit timezone and normalize to UTC."""
    if not isinstance(text, str) or not text.strip():
        raise ValueError('Timestamp must be a nonempty ISO timestamp with a timezone')
    value = text.strip()
    if value.endswith('Z'):
        value = value[:-1] + '+00:00'
    try:
        timestamp = datetime.fromisoformat(value)
    except ValueError as error:
        raise ValueError(f'Invalid ISO timestamp: {text!r}') from error
    if timestamp.utcoffset() is None:
        raise ValueError(f'Timestamp must include a timezone: {text!r}')
    return timestamp.astimezone(timezone.utc)


def load_events(path: str | Path) -> list[Event]:
    with open(path, newline='', encoding='utf-8') as stream:
        return [Event(row['category'], Decimal(row['amount']), row.get('timestamp'))
                for row in csv.DictReader(stream)]

