from datetime import datetime, timezone
from decimal import Decimal
from .parse import Event, parse_timestamp


def summarize(events: list[Event], *, since: datetime | None = None,
              until: datetime | None = None) -> dict:
    def normalize_bound(bound: datetime | None, name: str) -> datetime | None:
        if bound is None:
            return None
        if not isinstance(bound, datetime) or bound.tzinfo is None or bound.utcoffset() is None:
            raise ValueError(f'{name} must be a timezone-aware datetime')
        return bound.astimezone(timezone.utc)

    since = normalize_bound(since, 'since')
    until = normalize_bound(until, 'until')
    if since is not None and until is not None and since >= until:
        raise ValueError('since must be earlier than until')

    totals: dict[str, Decimal] = {}
    count = 0
    active_window = since is not None or until is not None
    for event in events:
        if active_window:
            if event.timestamp is None:
                raise ValueError('event is missing a timestamp')
            timestamp = parse_timestamp(event.timestamp)
            if since is not None and timestamp < since:
                continue
            if until is not None and timestamp >= until:
                continue
        totals[event.category] = totals.get(event.category, Decimal('0')) + event.amount
        count += 1
    return {'count': count,
            'totals': {key: str(totals[key]) for key in sorted(totals)}}
